import json
import argparse
from pathlib import Path

MAX_RETRIES = 3
STATE_FILE = Path("queue_state.json")


def load_state(path=STATE_FILE):
    if not path.exists():
        return {}
    return json.loads(path.read_text())


def save_state(state, path=STATE_FILE):
    path.write_text(json.dumps(state, indent=2))


def run_render(job_id):
    # real call shells out to the renderer
    raise NotImplementedError


def attempt(job_id, state, render=run_render):
    job = state.setdefault(job_id, {"attempts": 0, "state": "pending"})
    try:
        render(job_id)
        job["state"] = "done"
        return {"state": "done"}
    except Exception as e:
        job["attempts"] += 1
        if job["attempts"] >= MAX_RETRIES:
            job["state"] = "dead"
            return {"state": "dead", "why": "retry budget spent"}
        job["state"] = "failed"
        return {"state": "failed", "why": str(e)}


def resume(job_id, state):
    job = state.get(job_id)
    if job is None:
        raise KeyError(job_id)
    job["state"] = "pending"
    return job


def main():
    p = argparse.ArgumentParser()
    p.add_argument("job_id")
    p.add_argument("--resume", action="store_true")
    args = p.parse_args()
    state = load_state()
    if args.resume:
        resume(args.job_id, state)
    print(json.dumps(attempt(args.job_id, state)))
    save_state(state)


if __name__ == "__main__":
    main()

const SYMBOLS = { USD: '$', EUR: '€', GBP: '£' };

export function formatPrice(amount, currency = 'USD', opts = {}) {
  if (amount == null || Number.isNaN(Number(amount))) return '—';
  const n = Number(amount);
  const decimals = opts.decimals ?? 2;
  const abs = Math.abs(n).toFixed(decimals);
  const [int, frac] = abs.split('.');
  const grouped = int.replace(/\B(?=(\d{3})+(?!\d))/g, opts.sep ?? ',');
  const sym = SYMBOLS[currency] ?? currency + ' ';
  const body = frac ? `${grouped}.${frac}` : grouped;
  return (n < 0 ? '-' : '') + sym + body;
}

import json
import sys


def hex_to_rgb(h):
    h = h.lstrip('#')
    if len(h) == 3:
        h = ''.join(c * 2 for c in h)
    if len(h) != 6:
        raise ValueError(f'bad hex: {h}')
    return tuple(int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))


def luminance(rgb):
    def ch(c):
        return c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4
    r, g, b = (ch(c) for c in rgb)
    return 0.2126 * r + 0.7152 * g + 0.0722 * b


def contrast(a, b):
    la, lb = luminance(hex_to_rgb(a)), luminance(hex_to_rgb(b))
    hi, lo = max(la, lb), min(la, lb)
    return (hi + 0.05) / (lo + 0.05)


def check(pairs):
    problems = []
    for p in pairs:
        need = 3.0 if p.get('large') else 4.5
        ratio = contrast(p['fg'], p['bg'])
        if ratio < need:
            problems.append({'name': p['name'], 'ratio': round(ratio, 2), 'need': need})
    return problems


if __name__ == '__main__':
    data = json.load(open(sys.argv[1] if len(sys.argv) > 1 else 'tokens/colors.json'))
    bad = check(data['pairs'])
    for b in bad:
        print(f"{b['name']}: {b['ratio']} < {b['need']}")
    sys.exit(1 if bad else 0)

import re

TIME = re.compile(r'(\d+):(\d+):(\d+),(\d+)')


def to_seconds(ts):
    h, m, s, ms = map(int, TIME.match(ts).groups())
    return h * 3600 + m * 60 + s + ms / 1000


def parse(text):
    cues = []
    block = []
    for line in text.split('\n'):
        if line.strip() == '':
            if block:
                cues.append(_cue(block))
                block = []
        else:
            block.append(line)
    return cues


def _cue(block):
    idx = int(block[0])
    start, end = [t.strip() for t in block[1].split('-->')]
    return {
        'index': idx,
        'start': to_seconds(start),
        'end': to_seconds(end),
        'text': '\n'.join(block[2:]),
    }
